<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { ArrowLeftBold, ArrowRightBold, Download, Headset, Search, Setting, VideoPause, VideoPlay } from '@element-plus/icons-vue'
import { useRoute } from 'vue-router'
import axios from 'axios'
import { ElMessage } from 'element-plus'

interface Source { id: string; label: string; short: string; default: boolean }
interface Track { token:string; source:string; source_label:string; song_name:string; singers:string; album:string; format:string; file_size:string; duration:string; isrc:string; lossless:boolean; cover_url?:string; nas_present:boolean; apple_present:boolean; apple_pending?:boolean; presence_pending?:boolean }
interface AppleCatalogTrack { apple_id:string; title:string; artist:string; album:string; duration_ms:number; artwork_url:string; track_url:string; country:string }
interface Job { id:string; selected_track?:Track; status:string; nas_status:string; apple_status:string }
interface LyricLine { time:number; text:string }
interface DownloadDirectory { name:string; path:string }
interface DownloadItem { id:string; name:string; directory:string; progress:number; downloaded:number; total:number; speed:number; state:'starting'|'downloading'|'done'|'error'; message?:string }
interface WatchFolderOption { id:string; name:string; input_dir:string; enabled:boolean; auto_process:boolean }
const route = useRoute()
const query = ref(typeof route.query.q === 'string' ? route.query.q : '')
const sources = ref<Source[]>([]), selectedSources = ref<string[]>([]), results = ref<Track[]>([]), jobs = ref<Job[]>([]), watchFolders = ref<WatchFolderOption[]>([])
const searching = ref(false), sourceProgress = ref<Record<string,string>>({}), formatFilter = ref(''), sourceFilter = ref(''), configOpen = ref(false), savingConfig = ref(false), downloadSettingsOpen = ref(false), savingDownloadSettings = ref(false), directoryPickerOpen = ref(false)
const status = ref({ musicdl_connected:false, musicdl_error:'', nas_watch_folder_configured:false, apple_watch_folder_configured:false })
const targetConfig = ref({ nas_watch_folder_id:'', apple_watch_folder_id:'', apple_storefront:'cn', musicdl_base_url:'', musicdl_service_token_configured:false })
const appleCatalogResults = ref<AppleCatalogTrack[]>([]), appleCatalogLoading = ref(false)
const currentTrack = ref<Track | null>(null), audio = ref<HTMLAudioElement | null>(null), visualizer = ref<HTMLCanvasElement | null>(null), lyricsScroll = ref<HTMLElement | null>(null), playing = ref(false)
const currentTime = ref(0), totalTime = ref(0), volume = ref(75), lyricsOpen = ref(false), lyrics = ref<LyricLine[]>([]), downloadsOpen = ref(false), downloads = ref<DownloadItem[]>([]), downloadDirectories = ref<DownloadDirectory[]>([]), savedDownloadDirectories = ref<DownloadDirectory[]>([]), selectedDownloadTrack = ref<Track | null>(null)
let eventSource: EventSource | null = null; let pollTimer: number | null = null
const downloadStreams: EventSource[] = []
let audioContext: AudioContext | null = null; let analyser: AnalyserNode | null = null; let visualizerData: Uint8Array<ArrayBuffer> | null = null; let visualizerFrame = 0
const formats = computed(() => [...new Set(results.value.map(item => item.format.toUpperCase()).filter(Boolean))].sort())
const visibleResults = computed(() => results.value.filter(item => (!formatFilter.value || item.format.toUpperCase() === formatFilter.value) && (!sourceFilter.value || item.source === sourceFilter.value)))
const activeJobs = computed(() => jobs.value.some(job => !['completed','partial','failed'].includes(job.status)))
const activeLyric = computed(() => { let index=-1; for (let i=0;i<lyrics.value.length;i+=1) { if (lyrics.value[i].time<=currentTime.value+.2) index=i; else break } return index })
const sourceName = (source: Source) => (source.label || source.short).replace('音乐', '').trim()
const sourceState = (source: Source) => sourceProgress.value[source.id] || ''
function libraryLabel(track:Track) { return track.presence_pending ? '正在检查资料库' : track.apple_pending ? track.nas_present ? '飞牛有 · Apple 待确认' : 'Apple Music 待确认' : track.nas_present && track.apple_present ? '双库都有' : track.nas_present ? '仅飞牛有' : track.apple_present ? '仅 Apple Music 有' : '双库都没有' }
function libraryClass(track:Track) { return track.presence_pending ? 'pending' : track.nas_present && track.apple_present ? 'complete' : track.nas_present || track.apple_present ? 'partial' : 'missing' }
function completeActionLabel(track:Track) { return track.nas_present ? '补到 Apple Music' : track.apple_present ? '补到飞牛' : '补齐双库' }
function toggleSource(source:Source) { if (selectedSources.value.includes(source.id)) { if (selectedSources.value.length > 1) selectedSources.value = selectedSources.value.filter(id => id !== source.id) } else selectedSources.value.push(source.id) }
async function loadJobs() { jobs.value = (await axios.get<Job[]>('/api/acquisitions',{params:{limit:30}})).data; ensurePolling() }
async function loadInitialData() { const [statusResponse,configResponse,foldersResponse]=await Promise.all([axios.get('/api/discovery/status'),axios.get('/api/dual-library/config'),axios.get<WatchFolderOption[]>('/api/watch-folders/')]); status.value=statusResponse.data; targetConfig.value=configResponse.data; watchFolders.value=foldersResponse.data.filter(folder=>folder.enabled && folder.auto_process); if (status.value.musicdl_connected) { sources.value = (await axios.get<Source[]>('/api/discovery/sources')).data; selectedSources.value = sources.value.filter(item => item.default).map(item => item.id); const settings=(await axios.get('/api/discovery/download-settings')).data; downloadDirectories.value=settings.download_directories || []; savedDownloadDirectories.value=downloadDirectories.value.map(item=>({...item})) }; await loadJobs() }
function finishSearch() { searching.value=false; eventSource?.close(); eventSource=null }
function searchMusic() { const keyword=query.value.trim(); if (!keyword) return ElMessage.warning('请输入歌名、歌手或专辑'); eventSource?.close(); results.value=[]; sourceProgress.value={}; formatFilter.value=''; sourceFilter.value=''; searching.value=true; searchAppleCatalog(keyword); const params=new URLSearchParams({q:keyword,sources:selectedSources.value.join(',')}); eventSource=new EventSource(`/api/discovery/search?${params}`); eventSource.addEventListener('source_start', event => { sourceProgress.value[JSON.parse((event as MessageEvent).data).source]='搜索中' }); eventSource.addEventListener('source_done', event => { const data=JSON.parse((event as MessageEvent).data); sourceProgress.value[data.source]=`完成 · ${data.count} 条` }); eventSource.addEventListener('source_error', event => { sourceProgress.value[JSON.parse((event as MessageEvent).data).source]='搜索失败' }); eventSource.addEventListener('result', event => results.value.push(JSON.parse((event as MessageEvent).data))); eventSource.addEventListener('presence', event => { const update=JSON.parse((event as MessageEvent).data); const track=results.value.find(item=>item.token===update.token && item.source===update.source); if(track) Object.assign(track,update) }); eventSource.addEventListener('done',finishSearch); eventSource.addEventListener('error',() => { ElMessage.error('musicdl 搜索连接中断'); finishSearch() }) }
async function searchAppleCatalog(keyword:string) { appleCatalogLoading.value=true; appleCatalogResults.value=[]; try { appleCatalogResults.value=(await axios.get<AppleCatalogTrack[]>('/api/discovery/apple-catalog/search',{params:{q:keyword,country:targetConfig.value.apple_storefront || 'cn',limit:8}})).data } catch { appleCatalogResults.value=[] } finally { appleCatalogLoading.value=false } }
function comparable(value:string) { return (value || '').normalize('NFKC').toLocaleLowerCase().replace(/[^\p{L}\p{N}]/gu,'') }
async function markAppleAdded(track:AppleCatalogTrack) { try { await axios.post('/api/apple-library/entries',{...track,source:'catalog'}); for (const result of results.value) { if (comparable(result.song_name)===comparable(track.title) && comparable(result.singers)===comparable(track.artist)) { result.apple_present=true; result.apple_pending=true } }; ElMessage.success('已记录为 Apple Music 待确认；对应下载结果现在只会补到飞牛') } catch(error) { ElMessage.error(axios.isAxiosError(error) ? error.response?.data?.detail || '记录失败' : '记录失败') } }
async function completeLibraries(track:Track) { const desired_nas=!track.nas_present, desired_apple=!track.apple_present; if (!desired_nas && !desired_apple) return; if (desired_nas && !status.value.nas_watch_folder_configured) return ElMessage.error('请先配置飞牛补齐监控目录'); if (desired_apple && !status.value.apple_watch_folder_configured) return ElMessage.error('请先配置 Apple Music 补齐监控目录'); try { jobs.value.unshift((await axios.post('/api/acquisitions',{selected_track:track,desired_nas,desired_apple})).data); if(desired_apple){track.apple_present=true;track.apple_pending=true}; ElMessage.success(desired_nas && desired_apple ? '已创建双库补齐任务' : desired_nas ? '已创建飞牛补齐任务' : '已创建 Apple Music 补齐任务'); ensurePolling() } catch (error) { ElMessage.error(axios.isAxiosError(error) ? error.response?.data?.detail || '创建补齐任务失败' : '创建补齐任务失败') } }
function drawVisualizer() { const canvas=visualizer.value; if (!canvas) return; const context=canvas.getContext('2d'); if (!context) return; const ratio=window.devicePixelRatio || 1; const width=220*ratio, height=44*ratio; if (canvas.width!==width || canvas.height!==height) { canvas.width=width; canvas.height=height }; context.clearRect(0,0,width,height); if (analyser && visualizerData && !audio.value?.paused) analyser.getByteFrequencyData(visualizerData); const gradient=context.createLinearGradient(0,0,width,0); gradient.addColorStop(0,'#ffb46b'); gradient.addColorStop(1,'#ff6b9d'); context.fillStyle=gradient; const bars=40, gap=2*ratio, barWidth=(width-gap*(bars-1))/bars; for(let i=0;i<bars;i+=1){ const value=analyser && visualizerData && !audio.value?.paused ? visualizerData[Math.floor(i*visualizerData.length/bars)]/255 : .08; const barHeight=Math.max(2*ratio,value*height); const x=i*(barWidth+gap), y=(height-barHeight)/2; context.beginPath(); context.roundRect(x,y,barWidth,barHeight,Math.min(barWidth/2,2*ratio)); context.fill() } visualizerFrame=requestAnimationFrame(drawVisualizer) }
async function ensureAudioGraph() { if (!audio.value) return; if (!audioContext) { audioContext=new AudioContext(); const source=audioContext.createMediaElementSource(audio.value); analyser=audioContext.createAnalyser(); analyser.fftSize=128; analyser.smoothingTimeConstant=.8; source.connect(analyser); analyser.connect(audioContext.destination); visualizerData=new Uint8Array(analyser.frequencyBinCount); await nextTick(); drawVisualizer() } if (audioContext.state==='suspended') await audioContext.resume() }
async function playTrack(track: Track) { currentTrack.value = track; if (!audio.value) return; await ensureAudioGraph(); audio.value.src = `/api/discovery/stream/${encodeURIComponent(track.token)}`; loadLyrics(false); try { await audio.value.play() } catch { ElMessage.error('无法播放该曲目') } }
async function togglePlayback() { if (!audio.value || !currentTrack.value) return; if (audio.value.paused) { await ensureAudioGraph(); await audio.value.play() } else audio.value.pause() }
function formatTime(value:number) { const seconds=Math.floor(value || 0); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2,'0')}` }
function seek() { if (audio.value && totalTime.value) audio.value.currentTime=currentTime.value }
function setVolume() { if (audio.value) audio.value.volume=volume.value / 100 }
function stepTrack(direction:number) { if (!currentTrack.value) return; const index=visibleResults.value.findIndex(track=>track.token===currentTrack.value?.token); const next=visibleResults.value[index+direction]; if (next) playTrack(next) }
function parseLyrics(value:string) { const parsed:LyricLine[]=[]; for (const row of (value || '').split('\n')) { const matches=[...row.matchAll(/\[(\d{1,2}):(\d{2})(?:[.:](\d{1,3}))?\]/g)]; const text=row.replace(/\[[^\]]*\]/g,'').trim(); if (!text) continue; for (const match of matches) parsed.push({time:Number(match[1])*60+Number(match[2])+(match[3]?Number(`0.${match[3]}`):0),text}) } return parsed.sort((a,b)=>a.time-b.time) }
async function loadLyrics(open=true) { if (!currentTrack.value) return; if (open) lyricsOpen.value=true; try { lyrics.value=parseLyrics((await axios.get(`/api/discovery/lyrics/${encodeURIComponent(currentTrack.value.token)}`)).data.lyric || '') } catch { lyrics.value=[] } }
function seekToLyric(time:number) { if (!audio.value) return; audio.value.currentTime=time; currentTime.value=time }
function handleShortcut(event:KeyboardEvent) { const tag=(event.target as HTMLElement | null)?.tagName; if (['INPUT','TEXTAREA','SELECT'].includes(tag || '')) return; if (event.code==='Space') { event.preventDefault(); togglePlayback() } else if (event.altKey && event.code==='ArrowLeft') stepTrack(-1); else if (event.altKey && event.code==='ArrowRight') stepTrack(1) }
function addDownloadDirectory() { downloadDirectories.value.push({name:'',path:''}) }
function removeDownloadDirectory(index:number) { downloadDirectories.value.splice(index,1) }
function resetDownloadDirectories() { downloadDirectories.value=savedDownloadDirectories.value.map(item=>({...item})) }
async function saveDownloadSettings() { savingDownloadSettings.value=true; try { const response=await axios.put('/api/discovery/download-settings',{download_directories:downloadDirectories.value}); downloadDirectories.value=response.data.download_directories || []; savedDownloadDirectories.value=downloadDirectories.value.map(item=>({...item})); downloadSettingsOpen.value=false; ElMessage.success('下载目录已保存') } catch(error) { ElMessage.error(axios.isAxiosError(error) ? error.response?.data?.detail || '保存下载设置失败' : '保存下载设置失败') } finally { savingDownloadSettings.value=false } }
function startDownload(track:Track) { if(!downloadDirectories.value.length) { downloadSettingsOpen.value=true; ElMessage.warning('请先在下载设置中添加下载目录'); return } selectedDownloadTrack.value=track; directoryPickerOpen.value=true }
function formatBytes(value:number) { return `${(value/1048576).toFixed(1)} MB` }
function trackDownload(item:DownloadItem) { const progress=new EventSource(`/api/discovery/downloads/${encodeURIComponent(item.id)}/progress`); downloadStreams.push(progress); progress.addEventListener('progress',event=>{ const data=JSON.parse((event as MessageEvent).data); item.state=data.status==='error' ? 'error' : data.status==='done' ? 'done' : data.status==='downloading' ? 'downloading' : 'starting'; item.downloaded=data.downloaded || 0; item.total=data.total || 0; item.speed=data.speed || 0; item.progress=item.total ? Math.min(100,Math.round(item.downloaded/item.total*100)) : item.state==='starting' ? 4 : 8; item.message=data.message || ''; if(item.state==='done' || item.state==='error') { progress.close(); if(item.state==='done') ElMessage.success(`下载完成：${item.name}`) } }); progress.onerror=()=>{ if(!['done','error'].includes(item.state)) { item.state='error'; item.message='下载进度连接中断' }; progress.close() } }
async function startDownloadToDirectory(directory:DownloadDirectory) { const track=selectedDownloadTrack.value; if(!track) return; directoryPickerOpen.value=false; try { const response=await axios.post('/api/discovery/downloads',{token:track.token,directory_name:directory.name}); downloads.value.unshift({id:response.data.download_id,name:`${track.song_name} · ${track.singers}`,directory:directory.name,progress:4,downloaded:0,total:0,speed:0,state:'starting'}); downloadsOpen.value=true; trackDownload(downloads.value[0]) } catch(error) { ElMessage.error(axios.isAxiosError(error) ? error.response?.data?.detail || '下载启动失败' : '下载启动失败') } }
function ensurePolling() { if (activeJobs.value && pollTimer===null) pollTimer=window.setInterval(loadJobs,2000); else if (!activeJobs.value && pollTimer!==null) { window.clearInterval(pollTimer); pollTimer=null } }
async function retryJob(job:Job) { await axios.post(`/api/acquisitions/${job.id}/retry`); ElMessage.success('已重新提交失败目标'); await loadJobs() }
async function saveTargetConfig() { savingConfig.value=true; try { await axios.put('/api/dual-library/config',{nas_watch_folder_id:targetConfig.value.nas_watch_folder_id,apple_watch_folder_id:targetConfig.value.apple_watch_folder_id,apple_storefront:targetConfig.value.apple_storefront}); status.value=(await axios.get('/api/discovery/status')).data; targetConfig.value=(await axios.get('/api/dual-library/config')).data; configOpen.value=false; ElMessage.success('双库监控目录已保存') } catch (error) { ElMessage.error(axios.isAxiosError(error) ? error.response?.data?.detail || '保存目录失败' : '保存目录失败') } finally { savingConfig.value=false } }
const jobStatus:Record<string,string>={queued:'等待开始',preparing:'准备中',downloading:'下载中',validating:'校验中',completed:'已提交监控处理',partial:'部分失败',failed:'失败',waiting:'等待',submitted:'已进入监控目录',success:'成功',not_needed:'无需处理',handoff_pending:'等待 Apple Music 接收',received_unverified:'已接收，待快照确认',confirmed_present:'快照已确认'}
watch(activeLyric,async index=>{ if(index<0 || !lyricsOpen.value) return; await nextTick(); lyricsScroll.value?.querySelectorAll('button')[index]?.scrollIntoView({block:'center',behavior:'smooth'}) })
onMounted(async()=>{ window.addEventListener('keydown',handleShortcut); try { await loadInitialData(); if(query.value && status.value.musicdl_connected) searchMusic() } catch(error) { ElMessage.error(axios.isAxiosError(error) ? error.response?.data?.detail || '发现音乐初始化失败' : '发现音乐初始化失败') } })
onBeforeUnmount(()=>{ window.removeEventListener('keydown',handleShortcut); eventSource?.close(); downloadStreams.forEach(stream=>stream.close()); if(pollTimer!==null) window.clearInterval(pollTimer); if(visualizerFrame) cancelAnimationFrame(visualizerFrame); audio.value?.pause(); audioContext?.close() })
</script>

<template>
  <div class="discovery-page"><section class="musicdl-shell">
    <header class="discover-head"><div class="discover-brand"><img class="brand-icon" src="/musicdl-icon.svg" alt=""><div><strong>Musicdl</strong><span>由 MusicFlow 双库补齐驱动</span></div></div><form class="search-box" @submit.prevent="searchMusic"><el-icon><Search/></el-icon><input v-model="query" placeholder="搜索歌曲、艺人…"><button :disabled="searching || !status.musicdl_connected">{{ searching ? '搜索中' : '搜索' }}</button></form></header>
    <el-alert v-if="!status.musicdl_connected" class="connection-alert" type="error" :closable="false" show-icon :title="status.musicdl_error || '无法连接 musicdl 服务'"/>
    <template v-else><div class="sourcebar"><span class="sourcebar-label">音乐源</span><div class="chips"><button v-for="source in sources" :key="source.id" type="button" class="chip" :class="{on:selectedSources.includes(source.id)}" @click="toggleSource(source)"><i/>{{ sourceName(source) }}</button></div><div class="filters"><label>格式 <select v-model="formatFilter"><option value="">全部</option><option v-for="format in formats" :key="format" :value="format">{{ format }}</option></select></label><label>来源 <select v-model="sourceFilter"><option value="">全部来源</option><option v-for="source in sources" :key="source.id" :value="source.short">{{ sourceName(source) }}</option></select></label></div><button class="settings-button download-settings-button" type="button" @click="downloadSettingsOpen=true"><el-icon><Download/></el-icon>下载设置</button><button class="settings-button" type="button" @click="configOpen=true"><el-icon><Setting/></el-icon>双库设置</button><span class="search-status">{{ searching ? `搜索中 · ${visibleResults.length} 首` : results.length ? `共 ${visibleResults.length} 首` : '' }}</span></div><div v-if="Object.keys(sourceProgress).length" class="source-progress"><span v-for="source in sources.filter(item=>selectedSources.includes(item.id))" :key="source.id" :class="{busy:sourceState(source)==='搜索中'}">{{ sourceName(source) }} {{ sourceState(source) }}</span></div></template>
    <div class="search-columns" :class="{ 'has-catalog': appleCatalogLoading || appleCatalogResults.length }"><main class="results-wrap"><div v-if="visibleResults.length" class="results-head"><span/><span>曲目</span><span>双库状态</span><span>专辑</span><span>时长</span><span>格式</span><span>大小</span><span>来源</span><span/></div><div v-if="visibleResults.length" class="results-list" tabindex="0" aria-label="Musicdl 搜索结果"><article v-for="track in visibleResults" :key="`${track.source}-${track.token}`" class="result-row" :class="{playing:currentTrack?.token===track.token}" @dblclick="playTrack(track)"><div class="cover"><img v-if="track.cover_url" :src="track.cover_url" alt=""><el-icon v-else><Headset/></el-icon></div><div class="track"><strong :title="track.song_name">{{ track.song_name }}</strong><span>{{ track.singers || '未知歌手' }}</span><em :class="libraryClass(track)">{{ libraryLabel(track) }}</em></div><div class="library-presence"><span class="presence-label" :class="libraryClass(track)">{{ track.presence_pending ? '检查中' : libraryLabel(track) }}</span></div><div class="album">{{ track.album || '—' }}</div><div class="duration">{{ track.duration || '—' }}</div><div class="format" :class="{lossless:track.lossless}">{{ track.format || '—' }}</div><div class="size" :class="{lossless:track.lossless}">{{ track.file_size || '—' }}</div><div class="source"><span>{{ track.source_label || track.source }}</span></div><div class="row-action"><button class="icon-action primary" type="button" title="试听" @click="currentTrack?.token === track.token ? togglePlayback() : playTrack(track)"><el-icon><VideoPause v-if="currentTrack?.token===track.token && playing"/><VideoPlay v-else/></el-icon></button><button class="icon-action" type="button" title="下载" @click="startDownload(track)"><el-icon><Download/></el-icon></button><button v-if="!track.presence_pending && !(track.nas_present && track.apple_present)" class="complete-action" type="button" @click="completeLibraries(track)">{{ completeActionLabel(track) }}</button></div></article></div><div v-else class="empty-state"><div class="empty-bars"><i/><i/><i/><i/><i/><i/><i/></div><h2>{{ searching ? '正在逐条获取结果' : results.length ? '没有符合筛选条件的结果' : '从一句歌词开始' }}</h2><p>{{ searching ? '结果会随 musicdl 搜索逐条浮现。' : results.length ? '调整格式或来源筛选后再试。' : '输入关键词，结果会随搜索逐条浮现，不必等待整页加载。' }}</p></div></main>
    <section v-if="appleCatalogLoading || appleCatalogResults.length" class="apple-catalog"><div class="catalog-heading"><div><strong>Apple Music 曲库候选</strong><span>这里只表示 Apple 曲库可搜索到；在 Apple Music 中添加后再点“已添加”。</span></div><small>{{ targetConfig.apple_storefront.toUpperCase() }}</small></div><div v-loading="appleCatalogLoading" class="catalog-list" tabindex="0" aria-label="Apple Music 曲库候选结果"><article v-for="track in appleCatalogResults" :key="track.apple_id" class="catalog-item"><img v-if="track.artwork_url" :src="track.artwork_url" alt=""><div><strong>{{ track.title }}</strong><span>{{ track.artist }} · {{ track.album || '未知专辑' }}</span></div><div class="catalog-actions"><a :href="track.track_url" target="_blank" rel="noopener noreferrer">在 Apple Music 中打开</a><button type="button" @click="markAppleAdded(track)">已添加</button></div></article></div></section></div>
  </section><audio ref="audio" class="audio-player" preload="metadata" @play="playing=true" @pause="playing=false" @ended="stepTrack(1)" @loadedmetadata="totalTime=audio?.duration || 0" @timeupdate="currentTime=audio?.currentTime || 0"/><footer v-if="currentTrack" class="player-bar"><div class="player-now"><div class="player-cover"><img v-if="currentTrack.cover_url" :src="currentTrack.cover_url" alt=""><el-icon v-else><Headset/></el-icon></div><div class="player-meta"><strong>{{ currentTrack.song_name }}</strong><span>{{ currentTrack.singers }}</span></div><button class="lyric-button" type="button" :class="{on:lyricsOpen}" title="歌词" @click="loadLyrics(true)">词</button></div><div class="player-center"><div class="transport"><button type="button" title="上一首" @click="stepTrack(-1)"><el-icon><ArrowLeftBold/></el-icon></button><button class="main-play" type="button" :title="playing ? '暂停' : '播放'" @click="togglePlayback"><el-icon><VideoPause v-if="playing"/><VideoPlay v-else/></el-icon></button><button type="button" title="下一首" @click="stepTrack(1)"><el-icon><ArrowRightBold/></el-icon></button></div><div class="seek-row"><span>{{ formatTime(currentTime) }}</span><input v-model.number="currentTime" type="range" min="0" :max="totalTime || 0" step="0.1" @input="seek"><span>{{ formatTime(totalTime) }}</span></div></div><div class="player-right"><canvas ref="visualizer" class="visualizer"/><el-icon><Headset/></el-icon><input v-model.number="volume" type="range" min="0" max="100" @input="setVolume"></div></footer><button class="download-fab" type="button" title="下载列表" @click="downloadsOpen=true"><el-icon><Download/></el-icon><span v-if="downloads.length">{{ downloads.length }}</span></button><section v-if="jobs.length" class="job-panel"><div class="job-heading"><div><span>双库补齐任务</span><small>只下载并补充实际缺少的资料库</small></div><el-button text @click="loadJobs">刷新</el-button></div><div v-for="job in jobs.slice(0,5)" :key="job.id" class="job-row"><div><strong>{{ job.selected_track?.song